323	
324	    /**
325	     * The maximum number of owners permitted per city. Owner creation is rejected once the
326	     * owner's city already contains this many owners.
327	     */
328	    private static final int MAX_OWNERS_PER_CITY = 50;
329	
330	    /**
331	     * Counts how many existing owners live in the given city, compared case-insensitively.
332	     * This is evaluated before the new owner is persisted, so the owner being created is not
333	     * included in the count.
334	     *
335	     * @param city the new owner's city
336	     * @return the number of existing owners in that city
337	     */
338	    private int countOwnersInCity(String city) {
339	        int count = 0;
340	        for (Owner existing : this.clinicService.findAllOwners()) {
341	            if (city.equalsIgnoreCase(existing.getCity())) {
342	                count++;
343	            }
344	        }
345	        return count;
346	    }
347	
348	    /**
349	     * The maximum number of owners that may be created in a single business day. Owner
350	     * creation is rejected once this many owners already fall on the new owner's adjusted
351	     * business day {@code registrationDate}.
352	     */
353	    private static final int MAX_OWNERS_PER_DAY = 100;
354	
355	    /**
356	     * The fixed list of public holidays that the business-day roll skips over. A date that
357	     * lands on one of these is rolled forward to the next non-holiday business day.
358	     */
359	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
360	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
361	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
362	        LocalDate.parse("2026-12-28"));
363	
364	    /**
365	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
366	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
367	     * while a date that is already a non-holiday weekday is returned unchanged.
368	     *
369	     * @param date the date to adjust
370	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
371	     */
372	    private LocalDate toBusinessDay(LocalDate date) {
373	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
374	                || PUBLIC_HOLIDAYS.contains(date)) {
375	            date = date.plusDays(1);
376	        }
377	        return date;
378	    }
379	
380	    /**
381	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
382	     * registrationDate} rolls forward to the same business day. This is evaluated before the
383	     * new owner is persisted, so the owner being created is not included in the count.
384	     *
385	     * @param businessDay the adjusted business day to count against
386	     * @return the number of existing owners registered on that business day
387	     */
388	    private int countOwnersRegisteredOn(LocalDate businessDay) {
389	        int count = 0;
390	        for (Owner existing : this.clinicService.findAllOwners()) {
391	            LocalDate existingDate = existing.getRegistrationDate();
392	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
393	                count++;
394	            }
395	        }
396	        return count;
397	    }
398	
399	    /**
400	     * The number of owners that may be created on a single business day before a bulk-signup
401	     * warning is raised. Once more than this many owners already fall on the current business
402	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
403	     */
404	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
405	
406	    /**
407	     * Reports whether an unusually high number of owners have been created for today's business
408	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
409	     * the business day that {@code LocalDate.now()} rolls forward to.
410	     *
411	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
412	     */
413	    private boolean isBulkSignupDay() {
414	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
415	    }
416	
417	    /**
418	     * Builds the customer code for a newly created owner, formatted
419	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
420	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
421	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
422	     * first eight upper-case hex characters of the SHA-256 digest of
423	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
424	     * stable for a given telephone and last name rather than dependent on creation order.
425	     *
426	     * @param postcode            the owner's postcode (may be {@code null})
427	     * @param normalizedTelephone the owner's normalized E.164 telephone
428	     * @param lastName            the owner's last name
429	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
430	     */
431	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
432	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
433	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
434	    }
435	
436	    /**
437	     * De-duplicates a freshly computed {@code base} customer code against the codes already
438	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
439	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
440	     * yields a code no existing owner holds.
441	     *
442	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
443	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
444	     */
445	    private String deduplicatedCustomerCode(String base) {
446	        Set<String> existing = new HashSet<>();
447	        for (Owner owner : this.clinicService.findAllOwners()) {
448	            if (owner.getCustomerCode() != null) {
449	                existing.add(owner.getCustomerCode());
450	            }
451	        }
452	        if (!existing.contains(base)) {
453	            return base;
454	        }
455	        int n = 2;
456	        while (existing.contains(base + "-" + n)) {
457	            n++;
458	        }
459	        return base + "-" + n;
460	    }
461	
462	    /**
463	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
464	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
465	     *
466	     * @param source the string to hash
467	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
468	     */
469	    private static String sha256Hex8(String source) {
470	        try {
471	            byte[] digest = MessageDigest.getInstance("SHA-256")
472	                .digest(source.getBytes(StandardCharsets.UTF_8));
473	            StringBuilder hex = new StringBuilder(digest.length * 2);
474	            for (byte b : digest) {
475	                hex.append(String.format("%02x", b));
476	            }
477	            return hex.substring(0, 8).toUpperCase();
478	        } catch (NoSuchAlgorithmException e) {
479	            throw new IllegalStateException("SHA-256 not available", e);
480	        }
481	    }
482	
483	    /**
484	     * Builds the membership number for a newly created owner, formatted
485	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
486	     * customer code and {@code YY} is the last two digits of the fiscal year of the owner's
487	     * business-day-adjusted registration date, zero-padded to two digits. The fiscal year
488	     * starts on 1 July and is named by the calendar year it ends in.
489	     *
490	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
491	     * @param registrationDate the owner's business-day-adjusted registration date
492	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M27'})
493	     */
494	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
495	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
496	        return String.format("%s-M%02d", customerCode, Math.floorMod(fiscalYear, 100));
497	    }
498	
499	    /**
500	     * Counts how many existing owners share the given first and last name, compared
501	     * case-insensitively. This is evaluated before the new owner is persisted, so the
502	     * owner being created is not included in the count.
503	     *
504	     * @param firstName the new owner's first name
505	     * @param lastName  the new owner's last name
506	     * @return the number of existing owners with the same first and last name
507	     */
508	    private int countNamesakes(String firstName, String lastName) {
509	        int count = 0;
510	        for (Owner existing : this.clinicService.findAllOwners()) {
511	            if (firstName.equalsIgnoreCase(existing.getFirstName())
512	                && lastName.equalsIgnoreCase(existing.getLastName())) {
513	                count++;
514	            }
515	        }
516	        return count;
517	    }
518	
519	    /**
520	     * Canonical expansions applied to common street-type abbreviations during address
521	     * normalization. Keys and values are upper-cased so the lookup runs after the address
522	     * has itself been upper-cased.
523	     */
524	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
525	        "ST", "STREET",
526	        "RD", "ROAD",
527	        "AVE", "AVENUE");
528	
529	    /**
530	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
531	     * every run of internal whitespace is collapsed to a single space, the result is
532	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
533	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
534	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
535	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
536	     * returned and compared for household duplicates; an address that is blank once
537	     * normalized fails the required-field check.
538	     *
539	     * @param address the raw address value supplied by the client
540	     * @return the normalized address (empty string when {@code address} is null or blank)
541	     */
542	    /**
543	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
544	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
545	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
546	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
547	     * address returned is the normalized {@code addressLine1} with a single space and the
548	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
549	     * the flat {@code address} is normalized and returned, and the structured lines are left
550	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
551	     * downstream (household hash, postcode validation and locality); an owner that supplies
552	     * neither form yields an empty string, failing the required-address check.
553	     *
554	     * @param owner          the owner being created, whose structured address lines are set here
555	     * @param ownerFieldsDto the submitted owner fields
556	     * @return the composed, normalized address (empty string when no address form is supplied)
557	     */
558	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
559	        String addressLine1 = ownerFieldsDto.getAddressLine1();
560	        if (addressLine1 != null && !addressLine1.isBlank()) {
561	            String normalizedLine1 = normalizeAddress(addressLine1);
562	            owner.setAddressLine1(normalizedLine1);
563	            String addressLine2 = ownerFieldsDto.getAddressLine2();
564	            if (addressLine2 != null && !addressLine2.isBlank()) {
565	                String normalizedLine2 = normalizeAddress(addressLine2);
566	                owner.setAddressLine2(normalizedLine2);
567	                return normalizedLine1 + " " + normalizedLine2;
568	            }
569	            owner.setAddressLine2(null);
570	            return normalizedLine1;
571	        }
572	        owner.setAddressLine1(null);
573	        owner.setAddressLine2(null);
574	        return normalizeAddress(ownerFieldsDto.getAddress());
575	    }
576	
577	    private static String normalizeAddress(String address) {
578	        if (address == null) {
579	            return "";
580	        }
581	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
582	        if (collapsed.isEmpty()) {
583	            return "";
584	        }
585	        StringBuilder normalized = new StringBuilder(collapsed.length());
586	        for (String token : collapsed.split(" ")) {
587	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
588	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
589	            if (normalized.length() > 0) {
590	                normalized.append(' ');
591	            }
592	            normalized.append(expanded != null ? expanded : token);
593	        }
594	        return normalized.toString();
595	    }
596	
597	    /**
598	     * Normalizes a last name or address for household-duplicate comparison: leading and
599	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
600	     * single space and the result is lower-cased. Two owners are considered to share a
601	     * household when both their last names and addresses produce the same key.
602	     *
603	     * @param value the raw last name or address value
604	     * @return the normalized comparison key (empty string when {@code value} is null)
605	     */
606	    private static String householdKey(String value) {
607	        if (value == null) {
608	            return "";
609	        }
610	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
611	    }
612	
613	    /**
614	     * Derives the stable shared household identifier for the given normalized last name key
615	     * and postcode. The identifier is deterministic — the same household (same
616	     * {@link #householdKey normalized} last name and postcode) always maps to the same
617	     * value — so every owner in a household is assigned an identical id. It is the
618	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
619	     * '<lastNameKey>|<postcode>'}.
620	     *
621	     * @param lastNameKey the normalized last name key
622	     * @param postcode    the owner's postcode
623	     * @return the shared household identifier
624	     */
625	    private static String householdId(String lastNameKey, String postcode) {
626	        String source = lastNameKey + "|" + postcode;
627	        try {
628	            byte[] digest = MessageDigest.getInstance("SHA-256")
629	                .digest(source.getBytes(StandardCharsets.UTF_8));
630	            StringBuilder hex = new StringBuilder(digest.length * 2);
631	            for (byte b : digest) {
632	                hex.append(String.format("%02x", b));
633	            }
634	            return hex.substring(0, 12).toUpperCase();
635	        } catch (NoSuchAlgorithmException e) {
636	            throw new IllegalStateException("SHA-256 not available", e);
637	        }
638	    }
639	
640	    /**
641	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
642	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
643	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
644	     * collides with a computed household id.
645	     *
646	     * @param owner the existing owner
647	     * @return the owner's household id, or {@code null} when it has no postcode
648	     */
649	    private static String computeHouseholdId(Owner owner) {
650	        if (owner.getPostcode() == null) {
651	            return null;
652	        }
653	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
654	    }
655	
656	    /**
657	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
658	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
659	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
660	     * when mapping a collection to size every household from a single scan.
661	     *
662	     * @param ownerDto the dto to populate
663	     * @param owner    the owner being mapped
664	     */
665	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
666	        applyMembership(ownerDto, owner, householdSizes());
667	    }
668	
669	    /**
670	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
671	     * dto using a pre-computed map of household id to member count.
672	     *
673	     * @param ownerDto       the dto to populate
674	     * @param owner          the owner being mapped
675	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
676	     */
677	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
678	        int householdSize = owner.getHouseholdId() == null ? 1
679	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
680	        int points = MembershipPoints.points(owner, householdSize);
681	        ownerDto.setMembershipPoints(points);
682	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
683	    }
684	
685	    /**
686	     * Counts how many owners belong to each household, keyed by household id. Owners without a
687	     * household id (no postcode) are excluded — such an owner is its own single-member household.
688	     *
689	     * @return a map from household id to the number of owners sharing it
690	     */
691	    private Map<String, Integer> householdSizes() {
692	        Map<String, Integer> sizes = new java.util.HashMap<>();
693	        for (Owner existing : this.clinicService.findAllOwners()) {
694	            String householdId = existing.getHouseholdId();
695	            if (householdId != null) {
696	                sizes.merge(householdId, 1, Integer::sum);
697	            }
698	        }
699	        return sizes;
700	    }
701	
702	    /**
703	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
704	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
705	     * possible duplicate when an existing owner shares its last name (compared
706	     * case-insensitively with collapsed whitespace) and its postcode while having a
707	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
708	     * existing owner's id. When several existing owners match, the one with the lowest id
709	     * is chosen so the result is deterministic. When no such owner exists — or the new
710	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
711	     * and no matching id is recorded.
712	     *
713	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
714	     */
715	    private void applyPossibleDuplicate(Owner owner) {
716	        owner.setPossibleDuplicate(false);
717	        if (owner.getPostcode() == null) {
718	            return;
719	        }
720	        String lastNameKey = householdKey(owner.getLastName());
721	        Owner match = null;
722	        for (Owner existing : this.clinicService.findAllOwners()) {
723	            if (lastNameKey.equals(householdKey(existing.getLastName()))
724	                && owner.getPostcode().equals(existing.getPostcode())
725	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
726	                if (match == null || (existing.getId() != null
727	                    && existing.getId() < match.getId())) {
728	                    match = existing;
729	                }
730	            }
731	        }
732	        if (match != null) {
733	            owner.setPossibleDuplicate(true);
734	            owner.setPossibleDuplicateOf(match.getId());
735	        }
736	    }
737	
738	    /**
739	     * Builds the derived duplicate-detection identity key from an owner's normalized
740	     * telephone, email and household id, formatted {@code
741	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
742	     * duplicates only when their whole identity keys are equal; because the telephone is
743	     * part of the key, members of the same household with different telephones produce
744	     * different keys and are both allowed.
745	     *
746	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
747	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
748	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
749	     * @return the identity key string
750	     */
751	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
752	        return (normalizedTelephone == null ? "" : normalizedTelephone)
753	            + "|" + (email == null ? "" : email)
754	            + "|" + (householdId == null ? "" : householdId);
755	    }
756	
757	    /**
758	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
759	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
760	     * {@code null} when the owner has no email.
761	     *
762	     * @param email the existing owner's stored email (may be {@code null})
763	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
764	     */
765	    private static String emailForKey(String email) {
766	        return email == null ? null : email.trim().toLowerCase();
767	    }
768	
769	    /**
770	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
771	     * and brackets are stripped. When the number already carries a leading {@code '+'}
772	     * and country code these are kept; a number written in national trunk form (a leading
773	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
774	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
775	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
776	     * after the {@code '+'}, and its national-number length must be valid for the detected
777	     * country code (see {@link #hasValidNationalLength}).
778	     *
779	     * @param telephone the raw telephone value supplied by the client
780	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
781	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
782	     */
783	    private static String toE164(String telephone) {
784	        if (telephone == null) {
785	            return null;
786	        }
787	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
788	        String digits;
789	        if (cleaned.startsWith("+")) {
790	            digits = cleaned.substring(1);
791	        } else if (cleaned.startsWith("0")) {
792	            digits = "61" + cleaned.substring(1);
793	        } else {
794	            digits = "1" + cleaned;
795	        }
796	        if (!digits.matches("[0-9]{8,15}")) {
797	            return null;
798	        }
799	        if (!hasValidNationalLength(digits)) {
800	            return null;
801	        }
802	        return "+" + digits;
803	    }
804	
805	    /**
806	     * Validates the national-number length of an E.164 digit string against its country
807	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
808	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
809	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
810	     *
811	     * @param digits the E.164 digits (without the leading {@code '+'})
812	     * @return {@code true} when the national-number length is valid for the country code
813	     */
814	    private static boolean hasValidNationalLength(String digits) {
815	        if (digits.startsWith("61")) {
816	            return digits.length() - 2 == 9;
817	        }
818	        if (digits.startsWith("1")) {
819	            return digits.length() - 1 == 10;
820	        }
821	        return true;
822	    }
823	
824	    /**
825	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
826	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
827	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
828	     */
829	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
830	        "NSW", new int[] {2000, 2099},
831	        "VIC", new int[] {3000, 3099},
832	        "QLD", new int[] {4000, 4099});
833	
834	    /**
835	     * Validates an owner's postcode for creation. A postcode is only ever validated when
836	     * present (an absent postcode is optional and accepted). When present it must be exactly
837	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
838	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
839	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
840	     *
841	     * @param postcode the supplied postcode (never {@code null} here)
842	     * @param city     the owner's city, used to derive the region
843	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
844	     *         (signalling a 400 Bad Request)
845	     */
846	    private static boolean isValidPostcode(String postcode, String city) {
847	        if (!postcode.matches("[0-9]{4}")) {
848	            return false;
849	        }
850	        int[] range = REGION_POSTCODES.get(
851	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
852	        if (range == null) {
853	            return true;
854	        }
855	        int value = Integer.parseInt(postcode);
856	        return value >= range[0] && value <= range[1];
857	    }
858	
859	    /**
860	     * Disposable email domains that are not accepted for owner creation. An owner whose
861	     * email domain (compared case-insensitively) is in this set is rejected with a 400
862	     * Bad Request.
863	     */
864	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
865	        "mailinator.com", "tempmail.com", "guerrillamail.com");
866	
867	    /**
868	     * Normalizes an owner email for creation. A present email must be a syntactically
869	     * valid address whose domain is not on the disposable-domain blocklist ({@link
870	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
871	     *
872	     * @param email the raw email value supplied by the client (never {@code null} here)
873	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
874	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
875	     */
876	    private static String normalizeEmail(String email) {
877	        String trimmed = email.trim();
878	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
879	            return null;
880	        }
881	        String normalized = trimmed.toLowerCase();
882	        String domain = normalized.substring(normalized.indexOf('@') + 1);
883	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
884	            return null;
885	        }
886	        return normalized;
887	    }
888	}
